using System.Security.Cryptography;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.DataProtection;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;
using Microsoft.EntityFrameworkCore;
using ZfTools.Data;
using ZfTools.Services;

namespace ZfTools.Pages.Admin;

public class AdminModel(ToolDbContext db, SessionService session, IPasswordHasher<AppUser> hasher, IDataProtectionProvider protection) : PageModel
{
    private readonly IDataProtector secretProtector = protection.CreateProtector("ZfTools.DssSupplierSecrets.v1");
    public AppUser? Current { get; set; }
    public bool IsDss => Current?.Module == ToolModule.Dss;
    public string ModuleLabel => IsDss ? "DSS SIGNING" : "PKI CERTIFICATE";
    public List<AppUser> Users { get; set; } = [];
    public List<PkiTemplate> Templates { get; set; } = [];
    public List<DssProject> Projects { get; set; } = [];
    public string? Message { get; set; }
    [BindProperty] public string NewUsername { get; set; } = ""; [BindProperty] public string NewDisplayName { get; set; } = ""; [BindProperty] public string NewPassword { get; set; } = ""; [BindProperty] public int? NewProjectId { get; set; }
    [BindProperty] public string TemplateName { get; set; } = ""; [BindProperty] public string CertProfile { get; set; } = ""; [BindProperty] public string TemplateEnvironment { get; set; } = "development"; [BindProperty] public bool TemplateRequiresUnique { get; set; }
    [BindProperty] public string TemplateCertType { get; set; } = "diagUser"; [BindProperty] public string TemplateTrustGrade { get; set; } = "dev"; [BindProperty] public string TemplateDiagUserRole { get; set; } = "80";
    [BindProperty] public string ProjectCode { get; set; } = ""; [BindProperty] public string ProjectName { get; set; } = ""; [BindProperty] public string ProjectBaseUrl { get; set; } = ""; [BindProperty] public string ProjectAppKey { get; set; } = ""; [BindProperty] public string ProjectAppSecret { get; set; } = "";
    [BindProperty] public int? KeyProjectId { get; set; } [BindProperty] public string KeyName { get; set; } = ""; [BindProperty] public string KeyAlgorithm { get; set; } = "Ed25519";
    public async Task<IActionResult> OnGetAsync(CancellationToken ct) { if (!await LoadAsync(ct)) return RedirectToPage("/Index"); return Page(); }
    public async Task<IActionResult> OnPostCreateUserAsync(CancellationToken ct) { if (!await LoadAsync(ct)) return RedirectToPage("/Index"); if (string.IsNullOrWhiteSpace(NewUsername) || NewPassword.Length < 12) { Message = "请输入账号，并设置至少 12 位初始密码。"; return Page(); } if (IsDss && (NewProjectId is null || !await db.DssProjects.AnyAsync(x => x.Id == NewProjectId && x.Active, ct))) { Message = "请选择有效的 DSS 项目。"; return Page(); } if (await db.Users.AnyAsync(x => x.Module == Current!.Module && x.Username == NewUsername.Trim(), ct)) { Message = "该账号已存在。"; return Page(); } var user = new AppUser { Username = NewUsername.Trim(), DisplayName = string.IsNullOrWhiteSpace(NewDisplayName) ? NewUsername.Trim() : NewDisplayName.Trim(), Module = Current!.Module, Role = UserRole.User, DssProjectId = IsDss ? NewProjectId : null, MustChangePassword = true }; user.PasswordHash = hasher.HashPassword(user, NewPassword); db.Users.Add(user); await SaveAudit("create-user", user.Username, ct); return RedirectToPage(); }
    public async Task<IActionResult> OnPostToggleUserAsync(int id, CancellationToken ct) { if (!await LoadAsync(ct)) return RedirectToPage("/Index"); var user = await db.Users.SingleOrDefaultAsync(x => x.Id == id && x.Module == Current!.Module && x.Role == UserRole.User, ct); if (user is not null) { user.Active = !user.Active; await SaveAudit(user.Active ? "activate-user" : "revoke-user", user.Username, ct); await LoadAsync(ct); Message = user.Active ? "账号已激活。" : "账号已吊销。"; } return Page(); }
    public async Task<IActionResult> OnPostChangeProjectAsync(int id, int projectId, CancellationToken ct) { if (!await LoadAsync(ct)) return RedirectToPage("/Index"); if (!IsDss) return Forbid(); var user = await db.Users.SingleOrDefaultAsync(x => x.Id == id && x.Module == ToolModule.Dss && x.Role == UserRole.User, ct); var project = await db.DssProjects.SingleOrDefaultAsync(x => x.Id == projectId && x.Active, ct); if (user is null || project is null) { Message = "账号或项目不存在。"; return Page(); } var previous = user.DssProjectId; user.DssProjectId = project.Id; await SaveAudit("change-dss-project", $"{user.Username}:{previous}->{project.Code}", ct); Message = $"{user.Username} 的项目已更新为 {project.Code}，新权限立即生效。"; return Page(); }
    public async Task<IActionResult> OnPostResetPasswordAsync(int id, CancellationToken ct) { if (!await LoadAsync(ct)) return RedirectToPage("/Index"); var user = await db.Users.SingleOrDefaultAsync(x => x.Id == id && x.Module == Current!.Module && x.Role == UserRole.User, ct); if (user is not null) { var password = Convert.ToBase64String(RandomNumberGenerator.GetBytes(12)).Replace("=", ""); user.PasswordHash = hasher.HashPassword(user, password); user.MustChangePassword = true; await SaveAudit("reset-password", user.Username, ct); Message = $"@{user.Username} 的临时密码：{password}（仅显示一次，请交给用户）"; } return Page(); }
    public async Task<IActionResult> OnPostCreateTemplateAsync(CancellationToken ct) { if (!await LoadAsync(ct)) return RedirectToPage("/Index"); var role = TemplateDiagUserRole.Trim().Replace("0x", "", StringComparison.OrdinalIgnoreCase); var roleMask = System.Text.RegularExpressions.Regex.IsMatch(role, "\\A[0-9a-fA-F]{1,2}\\z") ? Convert.ToInt32(role, 16) : -1; if (IsDss || string.IsNullOrWhiteSpace(TemplateName) || string.IsNullOrWhiteSpace(CertProfile) || string.IsNullOrWhiteSpace(TemplateCertType) || string.IsNullOrWhiteSpace(TemplateTrustGrade) || roleMask <= 0 || (roleMask & 1) != 0) { Message = "请填写模板名称、cert_profile、证书类型、信任等级和有效角色位掩码（允许位：80/40/20/10/08/04/02）。"; return Page(); } db.PkiTemplates.Add(new PkiTemplate { DisplayName = TemplateName.Trim(), CertProfile = CertProfile.Trim(), EnvironmentName = TemplateEnvironment, RequiresEcuUniqueId = TemplateRequiresUnique, RequiredFields = TemplateRequiresUnique ? "ECUVariantID,ECUUniqueID" : "ECUVariantID", CertType = TemplateCertType.Trim(), TrustGrade = TemplateTrustGrade.Trim(), DiagUserRole = role }); await SaveAudit("create-pki-template", TemplateName, ct); await LoadAsync(ct); Message = "PKI 模板已新增。"; return Page(); }
    public async Task<IActionResult> OnPostCreateProjectAsync(CancellationToken ct) { if (!await LoadAsync(ct)) return RedirectToPage("/Index"); if (!IsDss || string.IsNullOrWhiteSpace(ProjectCode) || string.IsNullOrWhiteSpace(ProjectName)) { Message = "请填写项目代号和名称。"; return Page(); } db.DssProjects.Add(new DssProject { Code = ProjectCode.Trim(), DisplayName = ProjectName.Trim() }); await SaveAudit("create-dss-project", ProjectCode, ct); await LoadAsync(ct); Message = "DSS 项目已新增。"; return Page(); }
    public async Task<IActionResult> OnPostUpdateProjectAsync(int id, string baseUrl, string appKey, string? appSecret, string? certificatePath, string? certificatePassword, CancellationToken ct) { if (!await LoadAsync(ct)) return RedirectToPage("/Index"); if (!IsDss) return Forbid(); var project = await db.DssProjects.SingleOrDefaultAsync(x => x.Id == id, ct); if (project is null) { Message = "DSS 项目不存在。"; return Page(); } if (!string.IsNullOrWhiteSpace(baseUrl) && (!Uri.TryCreate(baseUrl, UriKind.Absolute, out var endpoint) || endpoint.Scheme != Uri.UriSchemeHttps)) { Message = "供应商接口地址必须使用 HTTPS。"; return Page(); } project.BaseUrl = baseUrl.Trim(); project.AppKey = appKey.Trim(); if (!string.IsNullOrWhiteSpace(appSecret)) project.AppSecret = secretProtector.Protect(appSecret); if (!string.IsNullOrWhiteSpace(certificatePath)) project.ClientCertificatePath = certificatePath.Trim(); if (!string.IsNullOrWhiteSpace(certificatePassword)) project.ClientCertificatePassword = secretProtector.Protect(certificatePassword); await SaveAudit("update-dss-project-config", project.Code, ct); await LoadAsync(ct); Message = $"{project.Code} 项目接口配置已保存。"; return Page(); }
    public async Task<IActionResult> OnPostCreateKeyAsync(CancellationToken ct) { if (!await LoadAsync(ct)) return RedirectToPage("/Index"); if (!IsDss || KeyProjectId is null || string.IsNullOrWhiteSpace(KeyName) || !System.Text.RegularExpressions.Regex.IsMatch(KeyName.Trim(), "\\A[A-Za-z0-9._-]{1,128}\\z") || KeyAlgorithm != "Ed25519") { Message = "请选择项目，并填写 1-128 位英文字母、数字、点、下划线或连字符组成的密钥名；当前算法为 Ed25519。"; return Page(); } db.DssKeys.Add(new DssKey { DssProjectId = KeyProjectId.Value, Name = KeyName.Trim(), SignAlgorithm = KeyAlgorithm.Trim() }); await SaveAudit("create-dss-key", KeyName, ct); Message = "DSS 密钥映射已新增。"; return RedirectToPage(); }
    private async Task<bool> LoadAsync(CancellationToken ct) { Current = await session.CurrentAsync(User, ct); if (Current?.Role != UserRole.Admin) return false; Users = await db.Users.Include(x => x.DssProject).Where(x => x.Module == Current.Module).OrderBy(x => x.Username).ToListAsync(ct); Templates = await db.PkiTemplates.Where(x => x.Active).OrderBy(x => x.DisplayName).ToListAsync(ct); Projects = await db.DssProjects.Include(x => x.Keys).Where(x => x.Active).OrderBy(x => x.Code).ToListAsync(ct); return true; }
    private async Task SaveAudit(string action, string details, CancellationToken ct) { db.AuditRecords.Add(new AuditRecord { UserId = Current!.Id, Action = action, Details = details }); await db.SaveChangesAsync(ct); }
}
